const $=id=>document.getElementById(id),all=units.flatMap(u=>u.stations);let state={completed:[],mistakes:[]},unit=0,session=null,storageOK=true;
try{const saved=JSON.parse(localStorage.getItem('taiwan-explorer-v1'));if(saved&&Array.isArray(saved.completed))state={completed:saved.completed.filter(id=>all.some(s=>s.id===id)),mistakes:Array.isArray(saved.mistakes)?saved.mistakes:[]}}catch(e){storageOK=false}
function save(){try{localStorage.setItem('taiwan-explorer-v1',JSON.stringify(state))}catch(e){storageOK=false}$('storageNote').textContent=storageOK?'':'此瀏覽器無法儲存進度；目前仍可遊玩，關閉後可能不會保留。'}
const completed=s=>state.completed.includes(s.id);
function unlocked(s){const list=units.find(u=>u.stations.includes(s)).stations.filter(x=>!x.side);if(s.side)return completed(list[0]);const i=list.indexOf(s);return i===0||completed(list[i-1])}
function pos(lat,lon){return [180+(lon-119.7)*120,80+(25.4-lat)*160]}
function render(){const u=units[unit];$('count').textContent=state.completed.length;$('done').textContent=`${state.completed.length} / ${all.length}`;$('bar').style.width=state.completed.length/all.length*100+'%';$('tabs').innerHTML=units.map((x,i)=>`<button class="${i===unit?'active':''}" data-unit="${i}" aria-pressed="${i===unit}">0${i+1}　${x.title}</button>`).join('');$('mapTitle').textContent=u.title;$('unitSub').textContent=u.subtitle;
$('stationList').innerHTML=u.stations.map((s,i)=>`<button class="station ${unlocked(s)?'':'locked'}" data-station="${s.id}" aria-label="${s.name}，${completed(s)?'已完成':unlocked(s)?'可探索':'待解鎖'}"><span class="station-icon">${s.icon}</span><span><strong>${s.side?'支線':String(i+1).padStart(2,'0')} · ${s.name}</strong><small>${s.place}</small></span><span class="status">${completed(s)?'✓':unlocked(s)?'→':'🔒'}</span></button>`).join('');drawMap();save()}
function drawMap(){const stations=units[unit].stations,pts=stations.filter(s=>!s.side).map(s=>pos(s.lat,s.lon).join(',')).join(' ');$('map').innerHTML=`<defs><pattern id="grid" width="40" height="40" patternUnits="userSpaceOnUse"><path d="M40 0H0V40" fill="none" stroke="#d9e6dc" stroke-width=".6"/></pattern><linearGradient id="land" x2="1" y2="1"><stop stop-color="#d7e3b1"/><stop offset="1" stop-color="#a5c498"/></linearGradient></defs><rect width="620" height="730" fill="url(#grid)"/><text x="35" y="355" class="waterlabel" transform="rotate(-68 35 355)">臺灣海峽</text><text x="493" y="345" class="waterlabel" transform="rotate(72 493 345)">太平洋</text><path d="M423 130 L455 126 466 148 446 167 442 198 428 229 425 266 408 311 390 352 372 391 351 427 326 465 305 504 294 546 284 590 270 619 258 601 252 568 233 540 216 520 207 487 208 455 215 421 225 390 239 358 255 330 269 299 284 272 300 248 315 220 337 198 353 174 380 155 402 143Z" fill="url(#land)" stroke="#86aa83" stroke-width="2"/><path d="M413 162 Q374 265 342 333 T282 561" stroke="#83a884" stroke-width="35" opacity=".25" fill="none"/><g fill="#91b18b" opacity=".6"><path d="M363 250l14-25 14 25zM329 324l16-30 16 30zM302 401l14-27 14 27zM284 463l13-25 13 25z"/></g><ellipse cx="401" cy="618" rx="7" ry="16" transform="rotate(20 401 618)" fill="#bed09c" stroke="#86aa83"/><text x="414" y="644" class="map-city">蘭嶼</text><text x="330" y="150" class="map-city">北部山區</text><polyline points="${pts}" fill="none" stroke="#b08e5b" stroke-width="2" stroke-dasharray="5 8" opacity=".65"/>`+stations.map((s,i)=>{const [x,y]=pos(s.lat,s.lon),done=completed(s),open=unlocked(s);const left=s.lon<121.2;return `<g class="map-node" tabindex="0" role="button" aria-label="${s.name}${open?'':'，待解鎖'}" data-station="${s.id}"><circle cx="${x}" cy="${y}" r="${open?17:13}" fill="${done?'#d77a39':open?'#286b59':'#a4b7a3'}" stroke="#fffdf4" stroke-width="4"/><text x="${x}" y="${y+4}" text-anchor="middle" fill="white" font-size="11" font-weight="bold">${done?'✓':s.side?'★':i+1}</text><text class="map-label" x="${x+(left?-24:24)}" y="${y+(unit===1&&i===6?26:4)}" text-anchor="${left?'end':'start'}">${s.name.replace('站','').replace('營地','').replace('聚落','')}</text></g>`}).join('')}
function start(id){const s=all.find(x=>x.id===id);if(!unlocked(s)){session=null;$('questContent').innerHTML=`<div class="dialog-top"><h2>🔒 再前進一小步</h2><button data-close="quest">✕</button></div><p>${s.side?'先完成本單元第一站，就能探索這條支線。':'完成本單元的前一站，就能解鎖這裡。'}</p><button class="primary" data-close="quest">回到地圖</button>`;$('quest').showModal();return}session={s,index:0,first:0,tries:0,order:[]};$('quest').showModal();question()}
function shuffle(a){return [...a].sort(()=>Math.random()-.5)}
function question(){const {s,index}=session,q=s.qs[index];session.tries=0;session.order=shuffle(q.options);$('questContent').innerHTML=`<div class="dialog-top"><div><span class="card-tag">${s.icon} ${s.name} · ${index+1} / 3</span><p class="location">📍 ${s.place}</p></div><button data-close="quest" aria-label="離開此站">✕</button></div><div class="bar"><i style="width:${index/3*100}%"></i></div><h2 class="question">${q.q}</h2><div class="options">${session.order.map((o,i)=>`<button class="option" data-answer="${i}">${String.fromCharCode(65+i)}　${o}</button>`).join('')}</div><div id="feedback" aria-live="polite"></div>`}
function answer(i){const q=session.s.qs[session.index],choice=session.order[i],btn=document.querySelector(`[data-answer="${i}"]`);if(choice===q.answer){if(session.tries===0)session.first++;btn.classList.add('correct');document.querySelectorAll('[data-answer]').forEach(b=>b.disabled=true);$('feedback').innerHTML=`<div class="feedback"><strong>答對了！找到新線索 ✨</strong><br>${q.e}</div><button class="primary" id="next">${session.index===2?'收下圖鑑卡':'下一道線索 →'}</button>`}else{session.tries++;btn.disabled=true;btn.classList.add('wrong');const key=session.s.id+':'+session.index;if(!state.mistakes.includes(key))state.mistakes.push(key);save();$('feedback').innerHTML=`<div class="feedback"><strong>再觀察一次，你可以的。</strong><br>提示：${q.e}<br>選另一個答案，繼續探索。</div>`}}
function next(){session.index++;if(session.index<3){question();return}const s=session.s;if(!completed(s))state.completed.push(s.id);save();render();$('questContent').innerHTML=`<div class="celebrate"><span class="card-tag">探索完成 · ${session.first} 題首次答對</span><div class="big">${s.icon}</div><h2>獲得「${s.card}」！</h2><p>${s.qs[0].e}</p><p>這站的三道線索都解開了。<br>圖鑑已收藏，回到地圖尋找下一個發現吧！</p><button class="primary" data-close="quest">回到探險地圖 →</button><button class="primary" id="review" style="background:#e7eddd;color:#286b59">再挑戰一次</button></div>`}
function album(){ $('cards').innerHTML=all.map(s=>`<article class="collect ${completed(s)?'':'unknown'}"><div class="emoji">${completed(s)?s.icon:'🔒'}</div><strong>${completed(s)?s.card:'尚未發現'}</strong><small>${s.name} · ${s.place}</small>${completed(s)?`<p>${s.qs[0].e}</p>`:''}</article>`).join('');$('album').showModal()}
document.addEventListener('click',e=>{const b=e.target.closest('button,[data-station]');if(!b)return;if(b.dataset.unit!==undefined){unit=Number(b.dataset.unit);render()}if(b.dataset.station)start(b.dataset.station);if(b.dataset.close)$(b.dataset.close).close();if(b.dataset.answer!==undefined)answer(Number(b.dataset.answer));if(b.id==='next')next();if(b.id==='review')startReview();if(b.id==='albumBtn')album();if(b.id==='reset'&&confirm('要清除所有站點進度與圖鑑收藏，重新開始嗎？')){state={completed:[],mistakes:[]};save();render()}});
function startReview(){session.index=0;session.first=0;question()}
$('map').addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.dataset.station){e.preventDefault();start(e.target.dataset.station)}});render();
